code='''from collections import Counter

def transform(grid):
    """Complete the rectangle and any repeated aligned guide lines."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]
    # Complete the outer frame around all the marked pixels.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == bg: out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == bg: out[r][c] = 2
    # Repeated marks on an aligned interior row/column indicate a guide line.
    row_counts = Counter(r for r, c in pts)
    col_counts = Counter(c for r, c in pts)
    for r, n in row_counts.items():
        if n >= 2:
            for c in range(c0, c1 + 1):
                if out[r][c] == bg: out[r][c] = 2
    for c, n in col_counts.items():
        if n >= 2:
            for r in range(r0, r1 + 1):
                if out[r][c] == bg: out[r][c] = 2
    return out
'''
